#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<vector<long long>> iv(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> iv[i][j];
        }
    }
    vector<long long> pts(q);
    for (int i = 0; i < q; i++) cin >> pts[i];

    sort(iv.begin(), iv.end());
    vector<int> order(q);
    for (int i = 0; i < q; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return pts[x] < pts[y]; });
    priority_queue<pair<long long, long long>, vector<pair<long long, long long>>, greater<pair<long long, long long>>> heap;
    vector<long long> ans(q, -1);
    long long i = 0;
    for (int idx : order) {
        long long p = pts[idx];
        while (i < n && iv[i][0] <= p) {
            heap.push({iv[i][1] - iv[i][0] + 1, iv[i][1]});
            i++;
        }
        while (!heap.empty() && heap.top().second < p) heap.pop();
        if (!heap.empty()) ans[idx] = heap.top().first;
    }
    for (int t = 0; t < q; t++) cout << (t ? " " : "") << ans[t];
    cout << "\n";

    return 0;
}

