import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] heap;
    static int heapSize;

    static void heapPush(long v) {
        int i = heapSize++;
        heap[i] = v;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] <= heap[i]) break;
            long t = heap[p];
            heap[p] = heap[i];
            heap[i] = t;
            i = p;
        }
    }

    static long heapPop() {
        long top = heap[0];
        heapSize--;
        if (heapSize > 0) {
            heap[0] = heap[heapSize];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, rr = l + 1, m = i;
                if (l < heapSize && heap[l] < heap[m]) m = l;
                if (rr < heapSize && heap[rr] < heap[m]) m = rr;
                if (m == i) break;
                long t = heap[m];
                heap[m] = heap[i];
                heap[i] = t;
                i = m;
            }
        }
        return top;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] iv = new long[(int) n][2];
        for (int i = 0; i < iv.length; i++) {
            for (int j = 0; j < iv[i].length; j++) {
                iv[i][j] = Long.parseLong(next());
            }
        }
        long[] pts = new long[(int) q];
        for (int i = 0; i < pts.length; i++) pts[i] = Long.parseLong(next());

        int cn = (int) n, cq = (int) q;
        long[] ik = new long[cn];
        for (int i = 0; i < cn; i++) ik[i] = (iv[i][0] << 30) | iv[i][1];
        Arrays.sort(ik);
        long[] qk = new long[cq];
        for (int i = 0; i < cq; i++) qk[i] = (pts[i] << 15) | i;
        Arrays.sort(qk);
        long[] ans = new long[cq];
        heap = new long[cn + 5];
        heapSize = 0;
        long mask = (1L << 30) - 1;
        int i = 0;
        for (int t = 0; t < cq; t++) {
            long p = qk[t] >> 15;
            int idx = (int) (qk[t] & 32767L);
            while (i < cn && (ik[i] >> 30) <= p) {
                long l = ik[i] >> 30, rr = ik[i] & mask;
                heapPush(((rr - l + 1) << 30) | rr);
                i++;
            }
            while (heapSize > 0 && (heap[0] & mask) < p) heapPop();
            ans[idx] = heapSize > 0 ? (heap[0] >> 30) : -1;
        }
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < cq; t++) {
            if (t > 0) out.append(" ");
            out.append(ans[t]);
        }
        System.out.println(out);
    }
}
